def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    # Extend the endpoint bars as vertical bands into the field.
    rows=[i for i,row in enumerate(grid) if any(v!=grid[0][0] and v!=1 for v in row)]
    # endpoints are horizontal colored bars on opposite boundary rows
    bars=[]
    for i,row in enumerate(grid):
        vals=[(j,v) for j,v in enumerate(row) if v not in (grid[0][0],1)]
        if len(vals)>=2: bars.append((i,[j for j,v in vals],vals[0][1]))
    if len(bars)>=2:
        (r1,c1,col1),(r2,c2,col2)=bars[0],bars[-1]
        # continuation occupies the inner portion of each endpoint bar
        for r in range(min(r1,r2)+1,max(r1,r2)):
            for c in c1[-2:]: out[r][c]=col1
            for c in c2[-2:]: out[r][c]=col2
    for r in range(h):
        for c in range(w):
            if grid[r][c]==1: out[r][c]=4
    return out
